  '따뜻한','세련된','편안한','정돈된','포근한','자연스러운','부드러운','날렵한','감각적인','부담 없는','여유 있는','단정한','화사한','깔끔한','고급스러운','중독성 있는','실용적인','완성도 높은','추천받는','신선한','귀여운','트렌디한','시크한','우아한','유연한','발랄한','가벼운','모던한','도톰한','슬림한','은은한','차분한','활동적인','유니크한','캐주얼한'
];
const defaultSituations = [
  '출근길에','약속 있을 때','하루 종일','아침마다','퇴근 후','주말마다','데이트할 때','비 오는 날','추운 날','늦잠 잔 날','급하게 나갈 때','기분 전환할 때','여행 갈 때','캠핑 갈 때','친구 만날 때','회식 있는 날','첫 출근 날','면접 전','중요한 자리','사진 찍는 날'
];
const defaultProducts = [
  '니트','원피스','셔츠','팬츠','아우터','코트','가디건','블라우스','점퍼','슬랙스','립밤','블러셔','데일리템','이너웨어','데님'
];

// 짧은/긴 문구 템플릿 분리
const shortTemplates = [
  '{adj} {sit}',
  '{adj} 감성',
  '{adj} 무드',
  '{adj} 추천',
