  '{adj} {sit}을 위한 추천',
  '{sit}에 어울리는 {adj} 스타일',
  '{adj} {sit}의 시작',
  '{sit}에 필요한 {adj} 감성',
  '오늘은 {adj} {sit}을 준비해보세요',
  '{adj} {sit}, 이 스타일로 완성하세요',
  '{adj} {sit} Pick!',
  '{adj} {sit} Best!',
  '{adj} {sit} Choice!',
  '{sit}에 꼭 맞는 {adj} 무드',
  '{adj} {sit} 한마디',
  '{adj} {sit}로 마무리하세요',
  '{adj} {sit}을 경험해보세요',
  '{adj} {sit}을 만나보세요',
  '{adj} {sit}을 위한 제안',
];

