function generatePhrases({
  adjectives,
  situations,
  product,
  includeProduct,
  sentenceCount = 1,
  maxLength = 20,
  outputCount = 10
}: {
  adjectives: string[],
  situations: string[],
  product: string,
  includeProduct: boolean,
  sentenceCount: number,
  maxLength: number,
  outputCount: number
}) {
  const phrases: string[] = [];
  for (let i = 0; i < outputCount; i++) {
    let lines: string[] = [];
    for (let j = 0; j < sentenceCount; j++) {
      const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
      const sit = situations[Math.floor(Math.random() * situations.length)];
      let line = includeProduct
        ? `${adj} ${sit} ${product}`
        : `${adj} ${sit}`;
      if (sentenceCount === 1) {
        line = line.slice(0, maxLength);
      } else {
        line = line.slice(0, 13);
      }
      lines.push(line);
    }
    phrases.push(lines.join('\\n'));
  }
  return phrases;
}

const handleGenerate = () => {
  const adjArr = adjectives.split(',').map(s => s.trim()).filter(Boolean);
