const customAdjectives = ['세련된', '단정한', '고급스러운', '깔끔한', '감각적인'];
const customSituations = ['퇴근 후', '주말마다', '데이트할 때', '비 오는 날', '중요한 날'];
const customTemplates = [
  '{sit}, {adj}해서 더 좋아요',
  '{adj} 무드, {sit}에 어울려요',
  '{sit}엔 {adj}한 선택이죠',
  '{adj}하게 어울리는 건 {sit}'
];

function generateCustomPhrases({
  adjectives,
  situations,
  sentenceCount = 1,
  outputCount = 5
}: {
  adjectives: string[],
  situations: string[],
  sentenceCount: number,
  outputCount: number
}) {
  const phrases: string[] = [];
  const usedCombos = new Set<string>();
  let tries = 0;
  while (phrases.length < outputCount && tries < 100) {
    let lines: string[] = [];
    let comboKey = '';
    for (let j = 0; j < sentenceCount; j++) {
      const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
      const sit = situations[Math.floor(Math.random() * situations.length)];
      const template = customTemplates[Math.floor(Math.random() * customTemplates.length)];
      let line = template.replace('{adj}', adj).replace('{sit}', sit);
      // 13자 제한
      line = line.slice(0, 13);
      lines.push(line);
      comboKey += adj + sit;
    }
    // 중복/어색 조합 방지
    if (!usedCombos.has(comboKey) && new Set(lines).size === lines.length) {
      phrases.push(lines.join('\\n'));
      usedCombos.add(comboKey);
    }
    tries++;
  }
  return phrases;
}

